    error( stringx(filename) + ": bad format; file must be updated" );
  for (serial_in(io,&cf); cf!=CHUNK_END; serial_in(io,&cf))
    {
    if (cf == CHUNK_SCRIPT_OBJECT)
      {
      script_object* so = new script_object;

if(so==0)
